-- Уточнения в 14 вопросах тем 03, 04, 05, 07 и 08 по полной проверке разделов.
-- Источник: scripts/questions/054_sections_review_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Пользовательский параметр myapp.currency в этом сеансе ещё ни разу не задавался. Что вернёт SELECT current_setting(''myapp.currency'', true);?', NULL, NULL, NULL, 'Пользовательский параметр myapp.currency не задан ни в файлах конфигурации, ни в настройках роли или базы, и в этом сеансе его тоже ни разу не задавали. Что вернёт SELECT current_setting(''myapp.currency'', true);?'),
        ('explanation', 'Пользовательский параметр myapp.currency не задан ни в файлах конфигурации, ни в настройках роли или базы, и в этом сеансе его тоже ни разу не задавали. Что вернёт SELECT current_setting(''myapp.currency'', true);?', NULL, NULL, 'Пользовательские параметры удобны как переменные сеанса. Их можно задать и в файле конфигурации, например через ALTER SYSTEM SET myapp.currency = ''RUB''; после перечитывания значение увидят все новые сеансы.', 'Пользовательские параметры удобны как переменные сеанса. Их можно задать и в файле конфигурации, тогда после перечитывания значение получат новые сеансы. В PostgreSQL 16 команда ALTER SYSTEM запишет такой параметр, только если его имя уже известно текущему сеансу, например после SET.'),
        ('option', 'Какие столбцы pg_settings показывают, из какого файла и с какой строки взято текущее значение параметра?', 'sourcefile и sourceline', NULL, 'Если текущее значение взято из файла конфигурации, они показывают файл и номер строки. Для других источников они пусты, как и для пользователя без прав суперпользователя или членства в роли pg_read_all_settings.', 'Если текущее значение взято из файла конфигурации, они показывают файл и номер строки. Для других источников они равны NULL, как и для пользователя без прав суперпользователя или членства в роли pg_read_all_settings.'),
        ('explanation', 'Какое представление показывает строки файлов конфигурации со столбцами applied и error?', NULL, NULL, 'pg_file_settings анализирует текущее содержимое конфигурационных файлов, а не состояние после последнего перечитывания. applied = true означает, что запись может быть успешно применена, но не подтверждает, что это значение уже действует в сеансе. Текущее значение проверяют через pg_settings или SHOW.', 'pg_file_settings анализирует текущее содержимое конфигурационных файлов, а не состояние после последнего перечитывания. applied = true означает, что запись может быть успешно применена, но не подтверждает, что это значение уже действует в сеансе. Текущее значение проверяют через pg_settings или SHOW. По умолчанию читать pg_file_settings могут только суперпользователи.'),
        ('question', 'Какие свойства транзакций в первую очередь обеспечивает многоверсионность?', NULL, NULL, NULL, 'Какие из перечисленных свойств транзакций в первую очередь обеспечивает многоверсионность?'),
        ('explanation', 'Какие из перечисленных свойств транзакций в первую очередь обеспечивает многоверсионность?', NULL, NULL, 'Многоверсионность обеспечивает изоляцию (снимки данных) и атомарность (версии строк прерванной транзакции остаются невидимыми); долговечность обеспечивает журнал предзаписи. Согласованность обеспечивают ограничения целостности.', 'Многоверсионность обеспечивает изоляцию (снимки данных) и атомарность (версии строк прерванной транзакции остаются невидимыми); долговечность обеспечивает журнал предзаписи. В курсе сказано, что многоверсионность обеспечивает первые три свойства ACID, включая согласованность: каждая транзакция видит согласованный снимок данных. Соблюдение ограничений целостности обеспечивают сами ограничения.'),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'Транзакция только помечается прерванной в clog, а созданные ею версии строк физически не удаляются', 'Не нужно восстанавливать каждую старую версию: транзакция помечается прерванной в clog, а лишние версии строк потом убирает очистка', 'В clog ставится статус «прервана»; ненужные версии строк потом уберёт очистка.', 'Версии строк прерванной транзакции не видны по её статусу, поэтому переписывать их обратно не нужно.'),
        ('explanation', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', NULL, NULL, 'Другие транзакции по статусу в clog увидят, что транзакция прервана, и проигнорируют её изменения, а ненужные версии строк позже уберёт очистка. Это не значит, что COMMIT и ROLLBACK всегда занимают одинаковое время: например, фиксация может ждать записи журнала на диск.', 'Другие транзакции по статусу в clog увидят, что транзакция прервана, и проигнорируют её изменения, а ненужные версии строк позже уберёт очистка. Кроме того, откат освобождает блокировки и другие ресурсы транзакции. Это не значит, что COMMIT и ROLLBACK всегда занимают одинаковое время: например, фиксация может ждать записи журнала на диск.'),
        ('explanation', 'Допишите команду, чтобы все запросы транзакции работали с одним снимком данных:
```
BEGIN ISOLATION LEVEL ___;
```', NULL, NULL, 'На уровне Repeatable Read снимок строится при первом операторе транзакции. Read Uncommitted работает как Read Committed.', 'На уровне Repeatable Read снимок строится при первом операторе, которому нужны данные (BEGIN снимок не берёт), и действует до конца транзакции. Read Uncommitted работает как Read Committed.'),
        ('option', 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', 'DROP TABLE будет ждать завершения транзакции A', NULL, 'Удалить таблицу, с которой работает другая транзакция, нельзя до её завершения.', 'Обычно блокировка освобождается при завершении A. Если A получила её после точки сохранения, блокировку освобождает и откат к этой точке.'),
        ('explanation', 'В транзакции после SAVEPOINT s вставлена строка. Какой номер транзакции окажется в xmin этой строки?', NULL, NULL, 'Связь подтранзакции с основной транзакцией хранится в pg_subtrans; при фиксации основной транзакции её подтранзакции тоже получают статус «зафиксирована». Функция pg_current_xact_id() внутри подтранзакции показывает номер основной транзакции, а номер подтранзакции виден в xmin: SELECT xmin, * FROM t;', 'Связь подтранзакции с основной транзакцией хранится в pg_subtrans. При фиксации основной транзакции фиксируются её неотменённые подтранзакции, а отменённые командой ROLLBACK TO остаются отменёнными. Функция pg_current_xact_id() внутри подтранзакции показывает номер основной транзакции, а номер подтранзакции виден в xmin: SELECT xmin, * FROM t;'),
        ('option', 'С какого места начинается восстановление после сбоя?', 'С первого файла WAL в каталоге', NULL, 'Журнал до последней контрольной точки не нужен.', 'Первые файлы в каталоге могут содержать старый журнал, который хранится для репликации или архива. Восстановление после сбоя начинается с позиции REDO последней завершённой контрольной точки.'),
        ('option', 'Когда контрольная точка считается выполненной?', 'Когда записаны все буферы, которые были грязными в момент её начала', NULL, 'Это гарантирует, что все изменения до этого момента уже на диске.', 'Тогда на диске гарантированно все изменения, сделанные до начала контрольной точки; более поздние изменения записывать к её завершению не требуется.'),
        ('option', 'Когда контрольная точка считается выполненной?', 'Когда буферный кеш полностью очищен', NULL, 'Буферы остаются в кеше, просто становятся чистыми.', 'Контрольная точка не освобождает буферный кеш: записанные страницы остаются в нём, а параллельные изменения снова делают часть буферов грязными.'),
        ('explanation', 'pg_test_fsync при двух записях по 8 КБ показал: open_datasync — 372 операции в секунду, fdatasync — 1338. Почему open_datasync медленнее?', NULL, NULL, 'В приведённом измерении при одной записи 8 КБ результаты близки. pg_test_fsync создаёт файл pg_test_fsync.out и нагружает диск, поэтому её запускают на учебной машине в отдельном пустом каталоге: /usr/lib/postgresql/16/bin/pg_test_fsync.', 'pg_test_fsync создаёт файл pg_test_fsync.out и нагружает диск, поэтому её запускают на учебной машине в отдельном пустом каталоге: /usr/lib/postgresql/16/bin/pg_test_fsync.'),
        ('option', 'Почему запись через журнал эффективнее, чем запись каждой изменённой страницы сразу на диск?', 'Журнал читается при каждом запросе', NULL, 'Журнал обычно не читается, пока не случится сбой.', 'Обычные запросы журнал не читают: таблицы читаются через буферный кеш. Журнал читают при восстановлении после сбоя и при репликации.'),
        ('option', 'Почему работа с временными таблицами быстрее, чем с обычными?', 'Они не журналируются и не попадают в общий буферный кеш', NULL, 'Используется локальный буфер процесса, журнал не пишется.', 'Данные временной таблицы не журналируются и обрабатываются в локальном буферном кеше сеанса.'),
        ('option', 'Что верно для временных таблиц?', 'Не журналируются', NULL, 'Поэтому работа с ними быстрее.', 'Отсутствие журнала для данных уменьшает накладные расходы на их изменение.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
